#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <string>
#include <unordered_map>
#include <memory>
#include <chrono>
#include <functional>
#include <atomic>
#include <vector>

struct AuthToken {
    std::string service_id;
    std::string token_value;
    std::chrono::steady_clock::time_point expires_at;
    bool revoked = false;
};

class TokenStore {
private:
    std::unordered_map<std::string, std::shared_ptr<AuthToken>> tokens_;
    mutable std::mutex mu_;
public:
    void store(const std::string& key, std::shared_ptr<AuthToken> token) {
        std::lock_guard<std::mutex> lock(mu_);
        tokens_[key] = std::move(token);
    }

    std::shared_ptr<AuthToken> get(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = tokens_.find(key);
        if (it == tokens_.end()) return nullptr;
        return it->second;
    }

    void revoke(const std::string& key) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = tokens_.find(key);
        if (it != tokens_.end()) {
            it->second->revoked = true;
        }
    }
};

class AuthValidator {
private:
    TokenStore& store_;
public:
    explicit AuthValidator(TokenStore& store) : store_(store) {}

    bool validate_token(const std::string& service_id) {
        auto token = store_.get(service_id);
        if (!token) return false;
        // Check expiration first
        if (std::chrono::steady_clock::now() >= token->expires_at) {
            return false;
        }
        // Snapshot revocation status
        bool is_revoked = token->revoked;
        return !is_revoked;
    }
};

struct Job {
    std::string id;
    std::string source_service;
    std::string payload;
    int priority;
};

class JobWorker {
private:
    std::queue<Job> queue_;
    std::mutex queue_mu_;
    std::condition_variable cv_;
    std::atomic<bool> running_{true};
    AuthValidator& validator_;
    TokenStore& token_store_;

    void process_job(const Job& job) {
        // Validate auth before processing
        if (!validator_.validate_token(job.source_service)) {
            std::cerr << "[REJECTED] Job " << job.id
                      << " from " << job.source_service
                      << ": auth failed\n";
            return;
        }

        // Simulate processing delay representing complex work
        std::this_thread::sleep_for(std::chrono::milliseconds(50));

        // Re-check authorization after processing delay
        // NOTE: We re-fetch the token and check it
        auto token = token_store_.get(job.source_service);
        if (!token || token->revoked) {
            std::cerr << "[LATE_REJECT] Job " << job.id
                      << ": token revoked during processing\n";
            return;
        }

        // Commit the result - in real system this writes to DB/sends response
        execute_privileged_action(job);
    }

    void execute_privileged_action(const Job& job) {
        std::cout << "[EXECUTED] Job " << job.id
                  << " from " << job.source_service
                  << ": " << job.payload << "\n";
    }

public:
    JobWorker(AuthValidator& validator, TokenStore& store)
        : validator_(validator), token_store_(store) {}

    void submit(Job job) {
        std::lock_guard<std::mutex> lock(queue_mu_);
        queue_.push(std::move(job));
        cv_.notify_one();
    }

    void run() {
        while (running_.load()) {
            Job job;
            {
                std::unique_lock<std::mutex> lock(queue_mu_);
                cv_.wait_for(lock, std::chrono::milliseconds(100),
                    [this] { return !queue_.empty() || !running_.load(); });
                if (!running_.load() && queue_.empty()) break;
                if (queue_.empty()) continue;
                job = std::move(queue_.front());
                queue_.pop();
            }
            process_job(job);
        }
    }

    void stop() {
        running_.store(false);
        cv_.notify_all();
    }
};

int main() {
    TokenStore store;

    // Register a service token valid for 5 seconds
    auto token = std::make_shared<AuthToken>();
    token->service_id = "payment-service";
    token->token_value = "sk_live_abc123";
    token->expires_at = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    store.store("payment-service", token);

    AuthValidator validator(store);
    JobWorker worker(validator, store);

    std::thread worker_thread([&worker] { worker.run(); });

    // Submit a job
    worker.submit({"job-001", "payment-service", "transfer $10000", 1});

    // Simulate: admin revokes the token 10ms after job submission
    std::thread revoke_thread([&store] {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        store.revoke("payment-service");
        std::cout << "[ADMIN] Token for payment-service revoked\n";
    });

    revoke_thread.join();
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    worker.stop();
    worker_thread.join();

    return 0;
}
